function LoginStatus({ isLoggedIn, username, unreadCount }) {
  return (
    <div>
      {/* Ternary — picks ONE of two things to render */}
      {isLoggedIn ? (
        <p>Welcome back, {username}!</p>
      ) : (
        <p>Please log in to continue.</p>
      )}

      {/* && — renders something ONLY if the condition is true, otherwise renders nothing */}
      {isLoggedIn && unreadCount > 0 && (
        <span className="badge">{unreadCount} new messages</span>
      )}
    </div>
  );
}

